def number(v):
 v=F(str(v)) if not isinstance(v,F) else v
 if v.denominator==1:return str(v.numerator)
 if v.denominator in [2,4,5,10,20,25,50,100]:return f'{float(v):.6f}'.rstrip('0').rstrip('.')
 return f'{v.numerator}/{v.denominator}'

