def course_bank():
 bank=[]
 def add(level,skill,n,title,prompt,correct,why,reason,params,visual=None,ui='reveal',hints=None,unit='',choices=None,wrong_reasons=None,action='図でたしかめる',control='動かしてたしかめる',initial_t=0):
  if choices is None:
   v=F(str(correct)) if not isinstance(correct,F) else correct
   vals=[v]
   for d in [v*2,v/2,v+1,v+2,v*3,v+3]:
    if d not in vals and d>=0:vals.append(d)
    if len(vals)==4:break
   choices=[number(x)+unit for x in vals];answer=0
  else:answer=choices.index(correct)
  reasons=[reason]+(wrong_reasons or ['見た目が似ているだけで決まるから','辺の長さや条件を考えなくてよいから'])
  q=dict(id=f'course4_{level}_{skill}_{n}',course=True,topic=level,level=level,family=skill,skill=title,
   prompt=prompt,choices=choices,answer=answer,reason_choices=reasons,reason_answer=0,explanation=why,
   params=params,visual=visual or skill,ui=ui,hints=hints or [reason,why],action=action,control=control,
   initial_t=initial_t,alt=title+'の問題図。'+prompt,bridge=LEVELS[level]['bridge'])
  digest=int(hashlib.sha256(q['id'].encode()).hexdigest()[:8],16)
  for ck,ak in [('choices','answer'),('reason_choices','reason_answer')]:
   shift=digest%len(q[ck]);q[ck]=q[ck][shift:]+q[ck][:shift];q[ak]=(q[ak]-shift)%len(q[ck])
  assert len(q['choices'])==len(set(q['choices'])),q['id']
  bank.append(q)
