LEARNING_PLANS.update({family:(cat,'beginner_lab',discovery,'問題に指定された形・長さ・個数') for family,(cat,discovery,operation) in BEGINNER_LABS.items()})
SUPPORTED_INTERACTIONS={'beginner_lab','static','inspect','sides','right_corner','equal_sides','circle','perimeter','compose','solid','fold_match','motion','diagonal','lshape','apex','cross'}


def attach_learning_plan(q):
    entry=LEARNING_PLANS.get(q.get('family'))
    if not entry:
        q['learning']={'category':'unclassified','goal':q.get('skill','図形の条件を読む'),'interaction':'static','operation':'静止図の条件を読む。図形を動かす操作はない。','discovery':'問題の条件を確認する','invariants':['問題文の条件'],'hint_steps':[{'text':v,'focus':'問題の条件'} for v in q.get('hints',[])]}
        return
    category,kind,discovery,preserve=entry
    # Existing family-specific instructions are retained only for explicitly approved handlers.
    operation=play_instruction(q) if kind not in ('inspect','lshape') else ('くぼみの点を下にドラッグまたは補助線ボタンで長方形2つに分割。左右の領域を選択し、足りない辺の長さを確認できる。全体を回転する操作はない。' if kind=='lshape' else '考え方を確認するボタンで、解法に対応する補助線・色分け・関係を段階的に確認できる。図形や頂点を動かす操作はない。')
    if kind=='beginner_lab':operation=BEGINNER_LABS[q['family']][2]
    q['learning']={'category':category,'goal':q['skill'],'interaction':kind,'operation':operation,'discovery':discovery,'invariants':[preserve],'hint_steps':[{'text':v,'focus':q['action']} for v in q['hints']]}
    validate_learning_plan(q)


def validate_learning_plan(q):
    plan=q['learning']
    if plan['interaction'] not in SUPPORTED_INTERACTIONS:raise ValueError('未実装の操作です: '+q['id'])
    if plan['category'] not in LEARNING_CATEGORIES:raise ValueError('学習分類が未定義です: '+q['id'])
    if not all(plan.get(k) for k in ('goal','operation','discovery','invariants')):raise ValueError('学習定義が不足しています: '+q['id'])
    if [s['text'] for s in plan['hint_steps']]!=q['hints']:raise ValueError('ヒントと学習定義が一致しません: '+q['id'])
    expected=LEARNING_PLANS[q['family']][1]
    if plan['category']!=LEARNING_PLANS[q['family']][0]:raise ValueError('学習分類が問題の目的と一致しません: '+q['id'])
    supported_visual={'diagonal':{'diagonal'},'lshape':{'lshape'},'cross':{'butterfly','trapezoid_cross'},'apex':{'area_ratio','cevians'},'circle':{'diameter'},'solid':{'box'}}
    if expected in supported_visual and q['visual'] not in supported_visual[expected]:raise ValueError('操作と図が一致しません: '+q['id'])
    if expected=='motion' and q['ui']!='motion':raise ValueError('変化の操作が未定義です: '+q['id'])
    if plan['interaction']!=expected:raise ValueError('解法に対応しない操作です: '+q['id'])


def play_instruction(q):
    if q.get('learning'):return q['learning']['operation']
    visual=q.get('visual');family=q.get('family')
    if visual=='diagonal':return '長方形には対角線が初めからある。対角線の端の点をドラッグ、または対角線スライダーで線を引き直せる。回転は解法ではない。'
    if visual=='butterfly':return '点Oを指で上下左右にドラッグできる。Oに合わせて上底ABが動く。ABとCDは平行、ABとCDの長さは変えられない。A/B/C/Dを個別に動かす操作はない。'
    if visual=='trapezoid_cross':return '点Oを左右だけにドラッグできる。上底ABが左右に動く。上下の底辺の長さ・平行・高さは固定。Oを上下に動かす操作はない。'
    if visual in ('area_ratio','cevians'):return '点Aを左右だけにドラッグできる。底辺BCと高さは固定。D/E/Pは条件に合わせて連動する。D/E/Pを個別に動かす操作はない。'
    if visual=='diameter':return '円周上の①②の点をそれぞれドラッグして半径の向きを回せる。中心は固定。'
    if visual=='box':return '立体をドラッグして見る向きを回せる。積み木の個数や辺の長さは変えられない。'
    if family in ('fold_match','equal_sides','compose','perimeter','sides','right_corner'):return {'fold_match':'折り線A/B/Cを選び、折る量をスライダーまたは指で変えられる。','equal_sides':'三辺を取り出してそろえる量をスライダーまたは指で変えられる。','compose':'対角線を選んで切り、三角形を指やスライダーで回して重ねられる。','perimeter':'周りの点を指で動かして一周たどれる。','sides':'辺をタップして数え、図形を回せる。','right_corner':'紙の角をドラッグして動かし、回して重ねられる。'}[family]
    if q.get('ui')=='motion':return '図形をドラッグ、またはスライダーで「'+str(q.get('control','位置'))+'」を変えられる。指定されていない頂点の個別移動はできない。'
    return '図形を動かす操作はない。問題の条件と段階ヒントを確認する。'


