def spatial_puzzle_questions():
    questions = []
    SUPPORTED_INTERACTIONS.add('spatial_puzzle')
    LEARNING_PLANS.update({
        family: (category, 'spatial_puzzle', discovery, invariant)
        for family, (category, discovery, operation, invariant) in PUZZLE_PLANS.items()
    })

    def add(level, family, n, skill, prompt, correct, explanation, params, choices, hints):
        category, discovery, operation, invariant = PUZZLE_PLANS[family]
        q = dict(id=f'spatial_{level}_{family}_{n}', course=True, topic=level, level=level,
                 family=family, visual=family, skill=skill, prompt=prompt, alt=skill,
                 params=params, choices=choices, answer=choices.index(correct), ui='reveal',
                 action=skill, control=operation, bridge=discovery, explanation=explanation, hints=hints,
                 reason_choices=[discovery], reason=0,
                 learning=dict(category=category, interaction='spatial_puzzle', goal=skill,
                               operation=operation, discovery=discovery, invariants=[invariant],
                               hint_steps=[dict(text=h, focus=skill) for h in hints]))
        validate_learning_plan(q)
        questions.append(q)

    letters = list('ABCD')
    for i, (mark, turns) in enumerate([
        ((0, -1), 1), ((-1, 0), 1), ((1, 0), 2),
        ((-2, -1), 1), ((1, -2), 2), ((2, 1), 3),
    ]):
        points = [mark]
        for _ in range(3):
            x, y = points[-1]
            points.append((-y, x))
        shift = (i * 3) % 4
        candidates = points[shift:] + points[:shift]
        correct = letters[candidates.index(points[turns])]
        turn_text = ['','4分の1回転','半回転','4分の3回転'][turns]
        add('beginner' if i < 3 else 'foundation', 'grid_turn', i % 3, '回した図の印をさがす',
            f'中心の黒い点を動かさずに、青い板を時計の針と同じ向きに{turn_text}します。★は A〜D のどこに移る？',
            correct, f'右へ4分の1回転する操作を{turns}回すると、★は {correct} に重なります。',
            dict(mark=mark, candidates=candidates), letters,
            ['黒い点が回転の中心だよ。', '上から右へ動くのが、時計の針と同じ向きだよ。',
             '右へ4分の1回転ずつ動かして、★を追いかけよう。'])

    for i, (axis, mark, candidates) in enumerate([
        ('vertical', (1, 1), [(3, 0), (3, 1), (4, 1), (3, 2)]),
        ('horizontal', (3, 1), [(3, 3), (2, 3), (3, 4), (4, 3)]),
        ('vertical', (0, 3), [(3, 3), (4, 2), (4, 3), (4, 4)]),
        ('descending', (0, 3), [(2, 0), (3, 1), (4, 0), (3, 0)]),
        ('ascending', (0, 1), [(3, 4), (4, 3), (3, 3), (2, 4)]),
        ('descending', (1, 4), [(3, 1), (4, 2), (4, 1), (4, 0)]),
    ]):
        x, y = mark
        reflected = {'vertical': (4-x, y), 'horizontal': (x, 4-y),
                     'descending': (y, x), 'ascending': (4-y, 4-x)}[axis]
        correct = letters[candidates.index(reflected)]
        add('beginner' if i < 3 else 'foundation', 'grid_reflect', i % 3, '折ると重なる場所をさがす',
            '赤い点線で紙を半分に折ります。★が重なるのは、A〜D のどのマス？',
            correct, f'折り線に直角な向きに、同じ距離だけ反対側へ移ると、★は {correct} に重なります。',
            dict(axis=axis, mark=mark, reflected=reflected, candidates=candidates), letters,
            ['赤い点線が折り線だよ。', '★から、折り線に直角な向きで進もう。',
             '折り線に着いたら、同じ長さだけ反対側まで進もう。'])

    directions = {(0,-1): 'N', (1,0): 'E', (0,1): 'S', (-1,0): 'W'}
    sides = dict(N='上', E='右', S='下', W='左')

    def side(origin, neighbor):
        return directions[tuple(b-a for a,b in zip(origin, neighbor))]

    for i, (path, gap) in enumerate([
        ([(0,1),(1,1),(2,1),(3,1)], 1),
        ([(0,2),(1,2),(1,1),(2,1),(3,1)], 1),
        ([(1,0),(1,1),(2,1),(2,2),(2,3)], 1),
        ([(0,2),(1,2),(1,1),(2,1),(3,1),(3,2),(4,2)], 2),
        ([(0,3),(1,3),(2,3),(2,2),(2,1),(3,1),(3,0)], 3),
        ([(0,4),(1,4),(1,3),(2,3),(2,2),(3,2),(4,2)], 3),
    ]):
        target = ''.join(sorted(side(path[gap], path[j]) for j in [gap-1, gap+1]))
        pieces = [target] + [p for p in ('EW','NS','EN','ES','NW','SW') if p != target][i % 3:i % 3+3]
        shift = (i+1) % 4
        pieces = pieces[shift:] + pieces[:shift]
        correct = letters[pieces.index(target)]
        roads = []
        for j, cell in enumerate(path):
            if j == gap:
                continue
            edges = [side(cell,path[k]) for k in (j-1,j+1) if 0 <= k < len(path)]
            roads.append((cell, edges))
        add('beginner' if i < 3 else 'foundation', 'path_piece', i % 3, '道のピースをはめる',
            'スタートからゴールまで道をつなげよう。向きを変えずに、空いているマスに入るピースは A〜D のどれ？',
            correct, f'空いたマスの道は{sides[target[0]]}と{sides[target[1]]}につながります。その2つの辺に出口があるのは {correct} です。',
            dict(size=4 if i<3 else 5, gap=path[gap], roads=roads, start=path[0], end=path[-1], pieces=pieces),
            letters, ['スタートから空いたマスまで、道をたどろう。',
                      'ゴールからも空いたマスまで戻ってみよう。',
                      '空いたマスのどの2辺から道が入るかを比べよう。'])

    for i, (heights, view) in enumerate([
        ([[1,2],[0,1]], 'top'),
        ([[1,2,0],[0,1,1]], 'top'),
        ([[1,2,0],[1,1,2]], 'front'),
        ([[1,3,1],[2,1,0],[0,2,1]], 'front'),
        ([[1,2,1],[2,1,0],[0,3,1]], 'right'),
        ([[2,0,3],[1,3,0],[3,1,2]], 'right'),
    ]):
        if view == 'top':
            visible = sum(h > 0 for row in heights for h in row)
            result = '上からは、いちばん上の積み木だけが見えるよ。'
        else:
            groups = list(zip(*heights)) if view == 'front' else heights
            maxima = [max(group) for group in groups]
            visible = sum(maxima)
            result = f'低い積み木は同じ列の高い積み木と重なります。列ごとの高さは {"、".join(map(str,maxima))} 段。'
        label = dict(top='真上', front='手前', right='右')[view]
        options = [f'{n}こ' for n in range(visible-1, visible+3)]
        shift = i % 4
        options = options[shift:] + options[:shift]
        add('beginner' if i < 3 else 'foundation', 'block_view', i % 3, '積み木を別の向きから見る',
            f'この積み木を{label}からまっすぐ見ると、見える正方形は全部で何こ？',
            f'{visible}こ', f'{result} 見える正方形は合わせて{visible}こです。',
            dict(heights=heights, view=view, label=label), options,
            ['どの向きから見るか、図のしるしを見よう。',
             '見る向きがそろうと、手前と奥の積み木が重なって見えるよ。',
             '見る向きを切り替え、見えている正方形を1こずつ数えよう。'])

    return questions


