                local=cursor.astimezone(ZoneInfo('Asia/Tokyo'));next_day=datetime.combine(local.date()+__import__('datetime').timedelta(days=1),datetime.min.time(),tzinfo=ZoneInfo('Asia/Tokyo')).astimezone(timezone.utc);stop=min(b,next_day);split.setdefault(local.date().isoformat(),[]).append((cursor,stop));cursor=stop
