        duration_estimates.append({**{k:recent[0][k] for k in ('profile_id','source_app','menu_id','difficulty_id','content_version','conditions')},'sample_count':sample,'recent_limit':10,'median_seconds':median,'measured_estimate_seconds':median if sample>=3 else None,'basis':'measured' if sample>=3 else 'insufficient_samples'})
