# Optional unit launch: only a consumed, non-expired ticket belonging to the verified
# learner can supply an assignment. A raw profile/menu query parameter is never trusted.
def cm_capture_plan_ticket(state):
    ticket = st.query_params.get('cm_launch')
    if isinstance(ticket,str) and 20 <= len(ticket) <= 256:
        digest = hashlib.sha256(ticket.encode()).hexdigest()
        if state.get('_cm_plan_fingerprint') != digest:
            state['_cm_plan_fingerprint'] = digest
            state['_cm_plan_ticket'] = ticket
            state.pop('_cm_plan_assignment',None)


def cm_verified_plan_assignment(state, profile, source, rows_reader):
    import uuid,datetime
    if not profile:
        return None
    cached = state.get('_cm_plan_assignment')
    if cached and cached.get('_profile') == str(profile):
        return {k:v for k,v in cached.items() if k!='_profile'}
    ticket = state.get('_cm_plan_ticket')
    if not ticket:
        return None
    params={'ticket_hash':'eq.'+hashlib.sha256(ticket.encode()).hexdigest(),
        'profile_id':'eq.'+str(profile),'source_app':'eq.'+source,
        'expires_at':'gt.'+datetime.datetime.now(datetime.timezone.utc).isoformat(),
        'select':'plan_item_id,menu_id,content_version,launch_mode,used_at','limit':'1'}
    try:
        rows = rows_reader(params)
    except Exception:
        return None
    if not isinstance(rows,list) or len(rows)!=1 or not rows[0].get('used_at') or not rows[0].get('plan_item_id'):
        return None
    row=rows[0]
    try:
        item=str(uuid.UUID(row['plan_item_id']))
    except (ValueError,TypeError,AttributeError):
        return None
    menu=row.get('menu_id'); version=row.get('content_version')
    if not isinstance(menu,str) or not menu.startswith(source+(':' if source=='soroban' else '.')) or len(menu)>160:
        return None
    if not isinstance(version,str) or len(version)>160:
        return None
    mode=row.get('launch_mode')
    if mode not in ('learn','challenge','review','reading_aloud'):
        return None
    out={'plan_item_id':item,'menu_id':menu,'content_version':version,'mode':mode,
         'nonce':state['_cm_plan_fingerprint'],'_profile':str(profile)}
    state['_cm_plan_assignment']=out
    state.pop('_cm_plan_ticket',None)
    return {k:v for k,v in out.items() if k!='_profile'}

_gx_plan_assignment=cm_verified_plan_assignment
def cm_verified_plan_assignment(state,profile,source,rows_reader):
    def reader(params):
        try:
            rows=rows_reader(params)
            gx_record('assignment_lookup','ok' if rows else 'not_found',response_count=len(rows) if isinstance(rows,list) else 0,trace_id=state.get('_cm_plan_fingerprint','')[:16])
            return rows
        except Exception as exc:
            gx_record('assignment_lookup','error',error_type=type(exc).__name__)
            raise
    result=_gx_plan_assignment(state,profile,source,reader)
    if result and state.get('_gx_last_assignment')!=result['nonce']:
        gx_record('assignment_ready',menu_id=result['menu_id'],trace_id=result['nonce'][:16]);state['_gx_last_assignment']=result['nonce']
    return result


def cm_grad_clean_changes(raw, menus, question_meta=None):
    """Validate preferences separately from learning events and scores."""
    from uuid import UUID
    if not isinstance(raw,list) or len(raw)>100:raise ValueError('invalid graduation changes')
    out=[];meta=question_meta or {}
    for value in raw:
        if not isinstance(value,dict):raise ValueError('invalid graduation change')
        op=str(UUID(str(value.get('operation_id'))));key=value.get('target_key');record=value.get('record')
        if not isinstance(key,str) or len(key)>512 or ':' not in key:raise ValueError('invalid graduation target')
        kind,target=key.split(':',1)
        if kind=='unit':
            if target not in menus:raise ValueError('unknown menu')
        elif kind=='question':
            if target not in meta:raise ValueError('unknown question')
        else:raise ValueError('invalid graduation target')
        base=value.get('base_version')
        if base is not None:base=str(UUID(str(base)))
        clean=None
        if record is not None:
            if not isinstance(record,dict) or not isinstance(record.get('graduated_at'),str):raise ValueError('invalid graduation record')
            clean={k:record[k] for k in ('graduated_at','recognition','menu_id','question_id','signature') if k in record}
            if len(str(clean.get('signature','')))>32768:raise ValueError('question signature too long')
            if kind=='unit':clean['menu_id']=target
            else:
                clean['question_id']=target;clean['catalog_question_id']=meta[target]['question_id'];clean['menu_id']=meta[target].get('menu_id') or meta[target].get('menu_ids',[None])[0]
                if clean['menu_id'] not in menus:raise ValueError('invalid question menu')
        out.append({'operation_id':op,'target_key':key,'base_version':base,'record':clean,'import_only':value.get('import_only') is True})
    return out

def cm_graduation_snapshot(rows, profile, source):
    if not isinstance(rows, list) or len(rows) > 1:
        raise ValueError('invalid graduation state')
    if not rows:
        return {}
    row = rows[0]
    if str(row.get('profile_id')) != str(profile) or row.get('source_app') != source:
        raise ValueError('graduation owner mismatch')
    items = row.get('items')
    if not isinstance(items, dict):
        raise ValueError('invalid graduation items')
    return {key: item for key, item in items.items()
            if key.startswith(('unit:', 'question:')) and isinstance(item, dict)}


def cm_geometry_graduation_sync(event,state,config):
    result={'ok':False,'request_id':event.get('request_id'),'profile_id':event.get('profile_id')}
    try:
        if not config:raise ValueError('unconfigured')
        profile=cm_verified_profile(state,config,event.get('credential'));result['profile_id']=profile
        if not profile or profile!=event.get('profile_id'):raise ValueError('profile mismatch')
        if event.get('changes') == []:
            rows = cm_rest(config, 'GET', '/rest/v1/chokomana_graduation_states', params={
                'profile_id': 'eq.' + profile, 'source_app': 'eq.geometry',
                'select': 'profile_id,source_app,items', 'limit': '1'})
            return dict(result, ok=True, items=cm_graduation_snapshot(rows, profile, 'geometry'))
        cm_publish_catalog(config,state)
        menus={r['entry_id'] for r in CM_CATALOG if r['entry_type']=='menu'}
        clean=cm_grad_clean_changes(event.get('changes'),menus,CM_META)
        proof=hashlib.sha256(('geometry:'+event['credential']).encode()).hexdigest()
        result.update(cm_rest(config,'POST','/rest/v1/rpc/chokomana_sync_graduations_v1',json={'p_device_hash':proof,'p_source_app':'geometry','p_changes':clean}))
    except Exception:result['error']='graduation_sync_failed'
    return result

def main():
    st.set_page_config(page_title='chokomana_ずけいのアトリエ',page_icon='🔷',layout='centered')
    st.markdown('<style>.block-container{padding-top:1rem;padding-bottom:0;max-width:820px}header[data-testid="stHeader"]{background:transparent}[data-testid="stMainBlockContainer"]{padding-left:.4rem;padding-right:.4rem}</style>',unsafe_allow_html=True)
    try:config=cloud_config()
    except ValueError as exc:st.error(str(exc));config=None
    state=st.session_state.setdefault('geometry_state',{})
    cm_capture_plan_ticket(state)
    ticket=st.query_params.get('cm_launch')
    if ticket and isinstance(ticket,str):
        marker=hashlib.sha256(ticket.encode()).hexdigest()
        if state.get('learning_launch_marker')!=marker:
            state.pop('learning_identity',None);state['response']={'configured':bool(config),'message':'連携を確認しています…'}
            gx_record('launch_received',trace_id=marker[:16],stage='ticket_captured')
        state['learning_launch_ticket']=ticket;state['learning_launch_marker']=marker
        try:del st.query_params['cm_launch']
        except Exception:pass
    state.setdefault('response',{'configured':bool(config),'message':'記録を準備しています…'})
    identity=state.get('learning_identity') or {}
    if identity.get('linked') and not state['response'].get('learning',{}).get('linked'):
        state['response']['learning']={**identity,**state['response'].get('learning',{}),'linked':True,'profile_id':identity['profile_id']}
    plan_profile=identity.get('profile_id') or state.get('response',{}).get('learning',{}).get('profile_id')
    plan_launch=cm_verified_plan_assignment(state,plan_profile,'geometry',lambda p:cm_rest(config,'GET','/rest/v1/chokomana_launch_tickets',params=p)) if config else None
    event=get_component(FRONTEND)(ux_server_records=state.get('ux_records',[])[-150:],ux_launch={'trace_id':state.get('learning_launch_marker','')[:16],'status':'verified' if plan_profile else 'waiting_identity','menu_id':(plan_launch or {}).get('menu_id',''),'stage':'assignment_ready' if plan_launch else 'assignment_pending'},graduation_result=(state.get('graduation_result') if (state.get('graduation_result') or {}).get('profile_id')==plan_profile else None),plan_launch=plan_launch,bank=BANK,topics=TOPICS,levels=LEVELS,response=state['response'],learning_info={'content_version':CM_CONTENT_VERSION,'question_meta':CM_META,'launch_marker':state.get('learning_launch_marker')},key='geometry_atelier_'+state.get('learning_launch_marker','standalone')[:16],default=None)
    if isinstance(event,dict) and event.get('action')=='graduation_sync':
        if event.get('request_id')!=state.get('graduation_last_request'):
            state['graduation_last_request']=event.get('request_id');state['graduation_result']=cm_geometry_graduation_sync(event,state,config);st.rerun()
        return
    if isinstance(event,dict) and event.get('request_id')!=state.get('last_request'):
        state['last_request']=event.get('request_id')
        try:
            previous_message=state['response'].get('message')
            import time
            began=time.perf_counter()
            state['response']=process_event(event,state,config)
            gx_record('component_response','ok' if state['response'].get('ok') else 'error',stage=str(event.get('type','unknown')),duration_ms=round((time.perf_counter()-began)*1000,2))
            if event.get('type') in ('assist','learning_sync') and previous_message:state['response']['message']=previous_message
        except (ValueError,TypeError,KeyError,AttributeError) as exc:
            gx_record('component_response','error',stage=str(event.get('type','unknown')),error_type=type(exc).__name__)
            state['response']={'request_id':event.get('request_id'),'configured':bool(config),'ok':False,'message':'同期する記録を確認できません。再読み込みしてください。'}
        st.rerun()


CHOKOMANA_SPEC = "ver.18追加：1回6問（復習は不足分を類題等で補充）。金6／銀5／銅4／白0〜3。初期目安270秒は仮設定。\n三角形は等寸のまま移動・回転し、空き枠の3頂点に近く一致したときだけはまる。\n傾斜出題：問題別の直近12回の初回回答を使用。再挑戦・同じ実施の再送は分母に重ねない。誤答が多い問題、直近誤答、ヒント使用、完全計測された長い回答時間の重みを上げる。3回以上の高正解率かつ直近3回連続正解で重みを下げる。新出題枠・同一回の種類分散・直近出題の減衰・後日の確認を残し、自動的な卒業や能力評価はしない。\n回答時間は問題別の有効中央値。同じ技能の他問題を優先して比較、少数なら同じ級の他問題、比較不足は45秒の仮基準。通信待ち・非表示・休憩・partial/unknownの時間を実測として混ぜない。長さのみで苦手と断定しない。\n統計と選択時の重み・根拠は既存ログ出力のadaptive_practiceおよびsession_started.payload.selection_policyから読める。生ログの保存先は維持。\nローカルは現在の学習者の共通イベントを使用。ちょこまなでサーバー検証済みprofile_idの同一学習者に限り、既存共通ログの最近1000イベント（出題・回答のみ）を初回同期時に取得しキャッシュ。上限に達した履歴は全期間の集計と扱わない。別の子どもの記録・所有者不明の旧履歴は傾斜計算へ混ぜない。追加DBテーブル・RLS変更・Secrets追加なし。実DBへの新規仕様変更はない。旧4問教材の成績・未送信ログは維持。\n以下は従来の基盤接続仕様と過去の検証記録。\n\nver.17追加：初級を20種類60問に拡張。中級以上の既存96問と既存初級24問は変更なし。1回4問、採点・メダル・ログは維持。旧教材版の未送信ログも再送可能。以下は従来の基盤接続仕様と過去の検証記録です。\n\n図形 ver.15 更新（2026-11-10 JST）\n対象 GitHub lstm500/chokomana_sansuu_zukei/main/app.py。GitHubのver.13を照合後、保存時に最新版ファイルver.14の更新を確認し、その終了画面UIを維持して再適用。\n追加：全5段階の終了画面に「TOPに戻る」「ちょこまなへ」を並置。ちょこまなは別タブで開き、起動チケット・秘密・profile_idを戻りURLに付けない。\nトップ左上の既存リンク、メダル（図／ず）・保存確認後の獲得通知、問題・採点・音声・旧履歴・共通ログの保存先は維持。\n保存待ちポップアップを閉じた場合も、結果/TOPで初めて保存確認した時に獲得を通知。同じACKで再通知しない。\n終了画面の振り返り時間を phase=other / activity_type=result_review として同じattempt_idに追記。完了スタンプを増やさない。\n結果表示・移動先（home/menu/new_challenge/chokomana_home）をlearning_activityに記録。非表示は除外、長い未観測停止はunknown。\n旧ver.13の未送信イベントも受理し、イベントID・本文・教材版を変更せず再送。教材内容は変えずcontent_versionは維持。\n今回追加のSQL・Secrets・requirements変更は不要。既存のGEOMETRY_APP_URLは教材台帳用で、そのまま維持。\n下記は引き継いだver.13の共通仕様・手順。現ファイルの配置名はapp.py_ver.15.py、GitHubではapp.pyへリネーム。\n今回の確認：jsdom＋fake-indexeddbで4問完了、TOP/集約リンク、保存確認後通知、再送通知抑止、振り返り/非表示区間、初回誤答後の正解、中断、新しい実施を確認。Pythonで旧版13/14・新版15のイベント受理、採点・スタンプ確認・集計を確認。Supabase実DBのロールバック試験で58イベントの追加区間、再送重複、スタンプ一意性、所有者照合と他児RLS拒否を確認（残存テストイベント0）。スタンプ判定からHTTP保存までの経路は模擬通信であり、本番Streamlitから集約表示までの全経路・実ブラウザの視覚表示は未確認。\n既存stamps.profile_idと共通events.profile_idは実DBでtext型を確認。いずれも検証済みUUID文字列を保存する。下記旧仕様のuuid表現は値の形式を指す。\n\n図形 ver.13：ちょこまな連携・設定・検証\n更新日：2026-11-09。対象は図形 app.py のみ。最新版として提供された app(20261107-144936).py は既存 ver.12 と一致したため、それを基に更新。\n\n【変更内容】\n・既存120問、5段階、4問チャレンジ、出題・図形操作・採点・音声・既存履歴 geometry_attempts_v1 は維持。\n・完了時、ちょこまなと同じCSSのメダル（図／ず）を表示。保存確認後のみ「デイリーメダルを獲得しました」。未連携・失敗時は未保存と端末保持を表示。\n・トップ左上に「← ちょこまなへ」。既存アプリのiframe内から確実に開けるよう別タブで開く。\n・共通仕様 chokomana.learning.v1 の追記型ログ、教材台帳、初回回答ベースのスタンプを追加。能力の断定や新しいAI評価、計画生成は追加していない。\n\n【必要な操作／DB実行順】\n1. app.py_ver.15.py を GitHub の対象図形リポジトリだけで app.py にリネームし置換する。起動方式・requirements・デプロイ構成の変更は不要。\n2. kotoba_app / keewulninyoeylgflshb の既存構成を確認済み。\n   2026-11-09 に不足していた chokomana_append_geometry_events_v1(text,jsonb) だけを追加済み。同梱SQLは適用内容の控え。現在の対象プロジェクトで再実行する必要はない。\n   既存 stamps・events・catalog・device_links・launch_tickets、既存RLS・GRANTは変更していない。新しいRPCは SECURITY INVOKER、空のsearch_path、service_roleのみ実行可能。\n3. 既存 SUPABASE_URL と SUPABASE_SERVICE_ROLE_KEY（または既存 SUPABASE_SECRET_KEY）を使用。公開ブラウザには送らない。連携先URLは指定プロジェクトであることを確認する。\n4. 任意で図形アプリ自身の公開URLを GEOMETRY_APP_URL に設定すると教材台帳の launch_url に入る。未設定は null。架空のURLを補わない。この設定も教材版に含め、同一版の内容差し替えを防ぐ。\n5. ちょこまなで対象の子どもを選び、図形を開く。既存の一回限りの cm_launch 起動チケットを受け取り、サーバーで所有者を検証する方式。アプリを直接開いただけでは、共通の学習者IDを推測して保存しない。\n\n【単体Pythonから取り出せる資料】\npython app.py_ver.15.py --chokomana-sql\npython app.py_ver.15.py --chokomana-catalog\npython app.py_ver.15.py --chokomana-spec\npython app.py_ver.15.py --chokomana-sample\npython app.py_ver.15.py --chokomana-summary 保存済みイベントJSONのパス\nSQL／台帳／仕様／例は標準出力へ。summary は共通 events 配列または配列を含むJSONから再計算する。集約アプリへ自動インストールする機能ではない。\n\n【共通データ仕様】\n既存の共通仕様を優先し、DBと生イベントの時間は整数ミリ秒（*_ms）。外部の時間表示・集約値は1000で割った秒。秒とミリ秒を同じ列へ混在させない。\nsource_app text 必須：geometry（国語 kotoba／そろばん soroban と共通）。\nprofile_id：既存スタンプではuuid、共通イベントではtext。検証された同じuuid文字列。未連携のローカルイベントだけnull。サーバー保存時には検証結果で確定する。\nattempt_id uuid 必須：新しい学習開始だけで生成。再表示・再送・通常の再読み込みは維持。\ncategory_key text 必須：スタンプは geometry。既存共通ログ／台帳の category_id='geometry' と同じ意味。勝手に共通DB列名を置換しない。\nmenu_id text 必須：geometry.level.beginner/intermediate/advanced/expert/master。難易度順1〜5。名称は初級・中級・上級・特級・名人。\nskill_id text：geometry.<問題family>。問題は skill_ids 配列で複数技能に対応。現教材では各問題1技能。台帳は5メニュー・40技能・120問。\nquestion_id text：geometry.<family>.<問題内容ハッシュ>。選択肢の表示順が変わっても同じID。問題文・条件・正解が変われば別ID。question_family_id は類題識別、related_material_id は共通の図・素材識別。元の問題IDも台帳snapshotに保存。\ncontent_version text 必須：教材全体の内容ハッシュ。問別 content_hash と solution_version も保持。旧版と混ぜて習熟判定しない。\noccurrence_id uuid：各出題で生成。再挑戦は別occurrence、親 parent_occurrence_id と retry_index で結ぶ。出題順 position は1始まり。\nevent_id uuid 必須・主キー：再送時同じID。segment_id uuid はページ実行ごと、sequence integer はsegment内の増分。受信順には依存しない。\noccurred_at UTC時刻文字列 必須。received_at はDB生成。event_hash は検証した正規化イベントのSHA256をサーバーで付加し、同一IDの異なる内容は拒否。\nevent_type/payload 必須。JSONの未観測値はnull、根拠なくfalse/0にしない。schema_version=1、app_version='13'。\n\nスタンプ：public.chokomana_stamps\n必須送信項目 profile_id/source_app/attempt_id/category_key/category_label/stamp_char/reading/difficulty/correct_count/total_count/grade/finished_at。\ncategory_label='図形'、stamp_char='図'、reading='ず'。difficultyは上記コード。終了UTC時刻。study_date/stamp_id/created_at は送らない。\nUNIQUE(profile_id,source_app,attempt_id) を利用。INSERT ON CONFLICT DO NOTHING相当＋再取得確認。完了詳細が揃うまで保存しない。途中終了・未回答はスタンプなし。\n4問：4正解gold、3silver、2bronze、0〜1white。再挑戦正解で初回成績を変更しない。\n既存の苦手克服は1〜4問になり得るため、4問以外は全問正解gold、ceil(問題数×5/6)以上silver、ceil(問題数×2/3)以上bronze、残りwhite。これは既存UI採点を変えずスタンプだけに適用する明示基準。\n\n【ログの取得方法】\npublic.chokomana_learning_catalog：source_app,entry_type,entry_id,content_version の既存一意制約。entry_type=menu/skill/question。payload JSONBに定義。版は追記し、同版上書きしない。\npublic.chokomana_learning_events：イベント台帳。source_app=geometry＋検証済みprofile_idで取得。event_idで重複排除。\npublic.chokomana_learning_response_facts：既存ビュー。メニュー・難易度・技能配列・初回／再回答・正誤・回答前支援を結合して読める。\npublic.chokomana_learning_duration_estimates：既存ビュー。学習者×アプリ×メニュー×難易度×教材版×設定条件ごとの完了時間中央値。直近10件、有効3件以上で measured_estimate_available。3件未満の中央値は参考値で、確定目安にはしない。\n集約側の本人認証・サーバー所有者検証は必須。任意のURL profile_idを本人確認にしない。既存RLSは authenticated の auth.uid() と自分のprofile_idを照合。集約側がservice_roleを使う場合も、先に既存の本人確認を行い自分のIDで絞る。\n例（サーバー側のパラメータ指定、:profile は検証済みID）:\n SELECT entry_type,entry_id,content_version,payload FROM public.chokomana_learning_catalog WHERE source_app='geometry' AND entry_type IN ('menu','skill');\n SELECT * FROM public.chokomana_learning_response_facts WHERE profile_id=:profile AND source_app='geometry';\n SELECT *,median_duration_ms/1000.0 AS median_seconds,measured_estimated_duration_ms/1000.0 AS estimate_seconds FROM public.chokomana_learning_duration_estimates WHERE profile_id=:profile AND source_app='geometry';\n SELECT event_id,attempt_id,occurrence_id,question_id,event_type,occurred_at,payload FROM public.chokomana_learning_events WHERE profile_id=:profile AND source_app='geometry' ORDER BY occurred_at,event_id;\nAPI取得では1000件などのレスポンス上限で打ち切らずページングする。クライアントへサービスキーを渡さない。question台帳の正解定義はサーバー用。一般公開読取を広げない。\n\n【進度・時間の解釈】\nsession_started：menu/category/difficulty/モード/予定問題数/設定/開始。session_ended：completed/abandoned等・出題数・回答数・終了。\nitem_presented：技能・順番・再挑戦の親・選択肢順・既知の答え露出。response_submitted：初回正誤、選択ID、再回答番号、回答前の支援、実学習待ち時間。理由回答は現UIにないためnull。\nsupport_used：図のヒント表示／AIまたは既存参照テキストの受信表示／回答後の解説／音声を区別。リクエストだけと実際の表示は別。親の支援は観測できずnull。\nlearning_activity：意味のある図形操作の開始・終了と到達状態。連続座標の全件保存はせず、操作だけで理解済みと判定しない。\n初回正解率＝親のない出題でresponse_index=1、automatic、answeredの正誤。ヒントありも含むため、その有無を別に読む。\n独力の指標では既往の答え露出・親支援などの不明値を除外。現状は不明が多いため分母0もある。別類題や後日の同問を区別できる証拠を返すが、習得・得意・苦手の断定はしない。中断の未回答は誤答にしない。\n\ntime_interval_closed：performance.now()を使い、学習できる表示から計測。UTCのstart_at/end_at、elapsed_ms、active_ms、excluded_ms、phaseを保存。\nphaseはthinking/answering/exploration/prompt/feedback等。回答後解説はfeedback。音声再生はpromptまたはfeedback。思考中の無操作を除外しない。\n非表示・明示休憩・blocking_waitを分離。現在のAIヒント通信中も図形を触れるのでblocking_waitにはしない。観測できない待ちを推測で作らない。明示休憩は計測APIに用意し、既存画面に不要な休憩ボタンは追加しない。\n10秒ごと＋操作・表示切替・終了時に区間を閉じる。未完了／中断の確定区間も当日の学習量に含める。\n集約側で「当日の実学習時間」を求める際は、同じprofile_idの全アプリから有効なactive区間を取得し、日付境界（Asia/Tokyo）で分割して、重なる[start_at,end_at)を和集合にして秒換算する。attempt合計やアプリ別秒数の単純加算はしない。active_ms=elapsed_msの実測区間だけを正確な区間として使い、混在・unknownは別枠。既存durationビューはメニュー別目安用で、一日の全体合計用ではない。\n再読み込みでは同じattempt/occurrenceを復元しsegmentを新しくする。中断中の空白時間は加算しない。復元後はpartialとして明記し、有効完了中央値から除く。Web Locksで同一attemptの複数タブ復元を防ぎ、未対応ブラウザは15秒リースを利用。別タブで別attemptを開始した重複時間は上記の和集合で除く。\n強制終了・OS停止・タブの破棄では最終区間が残らず、通常最大約10秒＋ブラウザ遅延分の欠測があり得る。時刻変更・スリープによる5秒超の時計差はpartial。計測精度は端末・ブラウザ依存。閉じられたタブは自力でsession_endedを確実送信できないので、終了イベントがないものは未完了として扱う。欠測を実測として補完しない。\n\n【教材メニュー・目安】\nメニューのskill_ids/available_skill_ids、難易度順、次級next_menu_idsを台帳へ保存。前提技能・対象年齢の根拠は未設定(null)。先の級は候補のみで、全技能の前提関係を捏造しない。\n初期目安 estimated_duration_ms=180000（180秒）は4問×45秒の運用上の仮設定。duration_basis='provisional'、sample_count=0。実測・科学的推奨時間ではない。1〜3問の復習では実際の問題数も併記し、4問の初期値を確定所要時間として扱わない。\n直接メニュー起動は未対応。supports_direct_launch=false、launch_urlは任意設定、selection_instructionsで「チャレンジまたは苦手克服→級選択」。現在の起動方式は変更しない。\n\n【識別・未送信記録・失敗時】\n別ドメインのlocalStorage共有を仮定しない。cm_launchはランダムな短寿命・一回限りの既存チケット。サーバーが既存chokomana_claim_learning_deviceで検証し、端末のランダム証明のハッシュをgeometry名義で対応付ける。URLからチケットを取り除き、キーや生チケットをブラウザログへ出さない。\n別の子どもはちょこまなで選び直して新しい起動チケットから開く。新チケットで新しいローカル学習者領域を作り、他タブの学習者はsessionStorageの識別を維持。以前の未連携記録を新しい子どもへ自動帰属させない。\nブラウザ変更・端末変更・保存削除時は、ちょこまなから開き直す。消した未送信履歴は復元できない。共有端末で以前の図形タブをそのまま渡すと以前の学習者なので、子どもの切替は必ずちょこまな側で行う。匿名認証や全員共通の固定IDは追加しない。\nIndexedDBにイベントを追記し、件数で切り捨てない。ACK後も原記録を残し、未送信マークだけ解除。1バッチ25件、通常約1.2秒のポーリング、未連携は30秒、通信失敗は最大5分まで後退。同じイベントID／attempt_idで再送。\n片方だけ保存できたときも再送で補う。メダル待ちも別途保持し、DB再取得で確認してから保存済みにする。既存UIの同期表示と追加詳細ログの同期状態は別。\n容量不足・保存不可時は未保存ありと表示し、既存学習を止めない。IndexedDB不可時はlocalStorageへ退避。両方不可ならメモリに一時保持されるが再読み込みで消えるため、保存済みとは扱わない。通常のブラウザによるサイトデータ削除・ストレージ退避では永続性を保証できない。\n旧 geometry_attempts_v1 はそのまま残す。旧記録の補助変換は端末別のlegacy_import領域に置き、本人不明なので共通DBへ自動移送しない。欠けた初回正誤・時間・支援情報を推測しない。\n\n【テスト結果と未確認事項】\nローカルStreamlit＋Chromium（390×850、タッチ設定）の実動作：4問完了、初回誤答→再挑戦正解、ヒント／解説表示、初回3/4で銀、未連携表示、実施ID・出題IDを維持した再読み込み、休憩・非表示区間、途中終了の記録、トップのリンクを確認。メダル保存ACKを模擬して獲得表示へ切り替わることも確認。ACKによって元イベントが削除・変更されないこと、複製したタブが同じ実施を復元しないこと、新しい起動マーカーで学習者領域が分離されること、ストレージ障害を模擬しても学習を続けられることを検証。新マーカーによる分離テストは本人認証成功の実証ではない。\nPython模擬通信：同じ完了の重複送信、新完了の追加、中断時スタンプなし、別学習者・未検証端末拒否、通信失敗後の同ID再送、初回成績維持、ヒントと解説・再回答区別、日付境界と時間重複排除、初期目安と実測不足の区別を検証。\nSupabase実接続：共通テーブル・権限・一意制約・識別RPCを確認。追加した図形RPCへブラウザテスト由来の検証済みイベントをトランザクション内で送信。同ID再送は重複せず、内容違いは拒否。既存スタンプの同一attempt一意性、anon実行不可、本人と他人のRLS読取を検証し全テストデータをロールバック。新RPCに関する追加セキュリティ警告なし。\n模擬のdont_know/skipped/timed_outは共通仕様の値検証のみ。現UIにない選択肢を追加したり、そのイベントが発生したと偽装していない。\n未確認：実運用のちょこまな起動→デプロイ済み図形→実際のサービスキー経由REST保存までの一連動作、実際の子ども・スマートフォン実機での音声／ストレージ挙動。既存音声の発話内容・設定・待ち時間は維持したが実機の発音・音質は未確認。GitHub・Streamlitへはまだ反映していない。\n集約側の変更は今回なし。既存の起動チケット／スタンプ一覧を利用する。詳細ログからの計画生成・全アプリ時間の和集合・未完了の扱い・この教材台帳の表示は集約側で必要に応じて対応する範囲。年齢×10分を推奨時間として表示せず、継続や使い切りを強制しない。\n"
